-- "#rrggbb" -> "rgb(rrggbb)" / "rgba(rrggbbaa)" for Hyprland color options
function M.rgb(name) return "rgb(" .. M[name]:gsub("^#", "") .. ")" end
function M.rgba(name, alpha) return "rgba(" .. M[name]:gsub("^#", "") .. (alpha or "ff") .. ")" end

